{
  "title": "零重力实验室",
  "scene": "你漂浮在零重力实验室中，四周是各种闪烁的仪器和悬浮的工具。空气循环系统突然发出警告音，一个显示屏上出现红色警告：‘空气过滤器故障，剩余时间 10 分钟’。实验室里有两个门，一个通向维修室，另一个通向备用空气滤清器室。维修室的门上有一个小标签，上面写着‘紧急维修工具’。备用滤清器室的门上有一个指示灯，但指示灯现在是坏的，无法显示状态。你注意到角落里有一个老旧的维修手册，但似乎很少有人翻阅过。",
  "goal": "修复空气过滤器或找到备用滤清器",
  "clue": "维修手册提及备用滤清器室的指示灯偶尔会故障，但实际滤清器状态良好。",
  "choices": [
    {
      "id": "A",
      "text": "前往维修室拿工具",
      "outcome": "你迅速前往维修室，找到了紧急维修工具。然而，返回实验室时发现空气已经变得稀薄，你感到呼吸困难，勉强完成了修复。你的健康值下降，但这总比没有空气好。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "直接去备用滤清器室",
      "outcome": "你决定直接前往备用滤清器室。尽管指示灯坏了，但你幸运地找到了状态良好的备用滤清器，并成功更换了故障的过滤器。实验室的空气恢复了正常。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "查看维修手册",
      "outcome": "你花时间查看了维修手册，发现备用滤清器室的指示灯偶尔会故障，但这并不影响滤清器的实际状态。你迅速前往备用滤清器室，找到了状态良好的备用滤清器，并成功更换了故障的过滤器。实验室的空气恢复了正常。然而，浪费的时间导致你的健康值有所下降。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
